find_rule:
js:
var d = [];
var html = getResCode();
/* TODO: 杂类/网页型规则，按站点结构解析。简单 HTML 可改用原生 DOM 链，例如:
   .list&&li;.title&&Text;.pic&&src;.info&&Text;a&&href */
var items = parseDomForArray(html, 'TODO_列表项选择器');
for (var i = 0; i < items.length; i++) {
  d.push({
    title: parseDomForHtml(items[i], 'TODO_标题选择器&&Text') || '',
    desc: parseDomForHtml(items[i], 'TODO_简介选择器&&Text') || '',
    img: parseDom(items[i], 'TODO_图片选择器&&src') + '@Referer=https://example.com',
    url: parseDom(items[i], 'TODO_链接选择器&&href'),
    col_type: 'text_2'
  });
}
setResult(d);

